1	import { describe, test, expect, vi, beforeEach } from 'vitest';
2	import { act } from '@testing-library/react';
3	import { useQueryClient, type QueryClient } from '@tanstack/react-query';
4	import type { ShopperBasketsV2Types } from 'commerce-sdk-isomorphic';
5	import { renderHookWithQueryClient } from 'app/test-utils/renderWithProviders';
6	import { useCartMergeAndCap, type CartCapBasket } from './useCartMergeAndCap';
7	
8	// Hoisted so the vi.mock factory below (hoisted above these imports by Vitest) can reference it —
9	// a plain `const` here would not yet be initialised at that point.
10	const { mockMutateAsync } = vi.hoisted(() => ({
11	  mockMutateAsync: vi.fn(),
12	}));
13	
14	vi.mock('@salesforce/commerce-sdk-react', () => ({
15	  useShopperBasketsV2Mutation: () => ({ mutateAsync: mockMutateAsync }),
16	}));
17	
18	// REWORK (round 1, SFCC-250 step 4.2): `@tanstack/react-query` is NOT mocked here any more. The
19	// mutation-in-flight guard used to read a React-render-time `useIsMutating()` snapshot (faked via
20	// a `mockUseIsMutating` hoisted mock in the original build of this test) — fixed to instead read
21	// `queryClient.isMutating()` live, inside `capBasketQuantities` itself, at the moment it actually
22	// runs (see `useCartMergeAndCap.ts`'s own comment on why). There is nothing left to fake:
23	// `useQueryClient`/`QueryClient`/`QueryClientProvider` were already real (previously via
24	// `importOriginal`, for the same reason the loop guard's `getQueryData`/`setQueryData` calls need
25	// a real cache), and the "mutation-in-flight guard" tests below now seed the real mutation cache
26	// directly instead of a mocked hook return value — exactly the "a real concurrent mutation starts
27	// elsewhere" shape the fix exists for.
28	
29	const makeLineItem = (
30	  overrides: Partial<ShopperBasketsV2Types.BasketProductItem> = {},
31	): ShopperBasketsV2Types.BasketProductItem => ({
32	  itemId: 'item-1',
33	  productId: 'product-1',
34	  quantity: 1,
35	  ...overrides,
36	});
37	
38	const makeBasket = (
39	  productItems: ShopperBasketsV2Types.BasketProductItem[],
40	  overrides: Partial<CartCapBasket> = {},
41	): CartCapBasket => ({
42	  basketId: 'basket-1',
43	  lastModified: '2026-09-20T00:00:00.000Z',
44	  productItems,
45	  ...overrides,
46	});
47	
48	// A short real macrotask flush — guaranteed to run after every currently-queued microtask
49	// (unlike a fixed number of `await Promise.resolve()` hops, which is easy to get wrong), so a
50	// test can observe "capBasketQuantities has started its own write and is now waiting on it"
51	// without yet resolving that write.
52	const flushMicrotasks = () => new Promise((resolve) => setTimeout(resolve, 0));
53	
54	/**
55	 * Starts a real, live in-flight mutation directly on the given QueryClient's own mutation
56	 * cache — bypassing React and any hook subscription entirely, the same way `useMutation().
57	 * mutate()` does internally (`MutationObserver` calls `mutationCache.build(client, options)`
58	 * then `.execute()` — confirmed against `node_modules/@tanstack/query-core/build/lib/
59	 * mutationCache.esm.js` and `mutation.esm.js`). Invoked directly here so nothing about it
60	 * depends on, or triggers, a React render — matching a real concurrent mutation happening
61	 * somewhere else in the app that a given hook instance has no subscription to. `execute()` is
62	 * deliberately not awaited: its `mutationFn` never resolves, and the synchronous portion of
63	 * `execute()` (up to its first internal `await`) already dispatches the `'loading'` status
64	 * before this function returns control, which is all `queryClient.isMutating()` needs to see it.
65	 * Call `.destroy()` on the returned mutation once a test is done asserting, to clear its pending
66	 * 5-minute GC timer (`Removable.scheduleGc`, `.../query-core/build/lib/removable.esm.js`) rather
67	 * than leaving a real dangling timer behind after the test ends.
68	 */
69	const seedInFlightMutation = (queryClient: QueryClient) => {
70	  const mutation = queryClient.getMutationCache().build(queryClient, {
71	    mutationFn: () => new Promise<never>(() => {}),
72	  });
73	  void mutation.execute();
74	  return mutation;
75	};
76	
77	describe('useCartMergeAndCap', () => {
78	  beforeEach(() => {
79	    vi.clearAllMocks();
80	    mockMutateAsync.mockResolvedValue({});
81	  });
82	
83	  describe("quantity boundary — fallback max of 3 (SFCC-268 not deployed, per this step's own pass criterion 6)", () => {
84	    test('line at 2: no change, no write', async () => {
85	      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
86	      const basket = makeBasket([makeLineItem({ quantity: 2 })]);
87	
88	      const outcome = await act(async () => result.current.capBasketQuantities(basket));
89	
90	      expect(outcome).toEqual({ status: 'not-needed' });
91	      expect(mockMutateAsync).not.toHaveBeenCalled();
92	    });
93	
94	    test('line at 3: no change — the >= boundary is 4, not 3 (== would wrongly leave 4 unreduced, not this case)', async () => {
95	      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
96	      const basket = makeBasket([makeLineItem({ quantity: 3 })]);
97	
98	      const outcome = await act(async () => result.current.capBasketQuantities(basket));
99	
100	      expect(outcome).toEqual({ status: 'not-needed' });
101	      expect(mockMutateAsync).not.toHaveBeenCalled();
102	    });
103	
104	    test('line at 4: reduced to 3', async () => {
105	      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
106	      const basket = makeBasket([makeLineItem({ itemId: 'a', productId: 'p-a', quantity: 4 })]);
107	
108	      const outcome = await act(async () => result.current.capBasketQuantities(basket));
109	
110	      expect(outcome).toEqual({ status: 'corrected' });
111	      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
112	      expect(mockMutateAsync).toHaveBeenCalledWith({
113	        parameters: { basketId: 'basket-1' },
114	        body: [{ itemId: 'a', productId: 'p-a', quantity: 3 }],
115	      });
116	    });
117	
118	    test('line at 5: reduced to 3, not to 4 — proves the check is a range (> max), not equality against max + 1', async () => {
119	      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
120	      const basket = makeBasket([makeLineItem({ itemId: 'a', productId: 'p-a', quantity: 5 })]);
121	
122	      const outcome = await act(async () => result.current.capBasketQuantities(basket));
123	
124	      expect(outcome).toEqual({ status: 'corrected' });
125	      expect(mockMutateAsync).toHaveBeenCalledWith({
126	        parameters: { basketId: 'basket-1' },
127	        body: [{ itemId: 'a', productId: 'p-a', quantity: 3 }],
128	      });
129	    });
130	
131	    test('two same-SKU lines already sum_quantities-merged into one line at 4: capped to one line at 3', async () => {
132	      // sum_quantities merging (step 4.1, useWishlistAuthDrawer.ts) already consolidates two
133	      // same-SKU lines server-side before this function ever sees the basket — this proves this
134	      // function correctly caps the already-merged single line, not that it performs
135	      // consolidation itself (this function never sees two separate same-SKU lines).
136	      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
137	      const basket = makeBasket([makeLineItem({ itemId: 'merged', productId: 'p-merged', quantity: 2 + 2 })]);
138	
139	      const outcome = await act(async () => result.current.capBasketQuantities(basket));
140	
141	      expect(outcome).toEqual({ status: 'corrected' });
142	      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
143	      expect(mockMutateAsync).toHaveBeenCalledWith({
144	        parameters: { basketId: 'basket-1' },
145	        body: [{ itemId: 'merged', productId: 'p-merged', quantity: 3 }],
146	      });
147	    });
148	
149	    test('a compliant product carrying a real c_maxOrderQuantity is capped to that value, not the fallback', async () => {
150	      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
151	      const basket = makeBasket([makeLineItem({ quantity: 8, c_maxOrderQuantity: 5 } as never)]);
152	
153	      const outcome = await act(async () => result.current.capBasketQuantities(basket));
154	
155	      expect(outcome).toEqual({ status: 'corrected' });
156	      expect(mockMutateAsync).toHaveBeenCalledWith(
157	        expect.objectContaining({ body: [expect.objectContaining({ quantity: 5 })] }),
158	      );
159	    });
160	  });
161	
162	  describe('mutation-in-flight guard — reads the live QueryClient state, not a render-time snapshot', () => {
163	    test('a mutation already in flight when the guard is checked (after an intervening re-render): returns skipped without issuing a write', async () => {
164	      const { result, rerender } = renderHookWithQueryClient(() => ({
165	        cap: useCartMergeAndCap(),
166	        queryClient: useQueryClient(),
167	      }));
168	
169	      const inFlight = seedInFlightMutation(result.current.queryClient);
170	      rerender(); // an intervening re-render — the case this guard has always correctly caught
171	      expect(result.current.queryClient.isMutating()).toBe(1); // sanity check on the seed itself
172	
173	      const basket = makeBasket([makeLineItem({ quantity: 5 })]);
174	      const outcome = await act(async () => result.current.cap.capBasketQuantities(basket));
175	
176	      expect(outcome).toEqual({ status: 'skipped', reason: 'mutation-in-flight' });
177	      expect(mockMutateAsync).not.toHaveBeenCalled();
178	      inFlight.destroy();
179	    });
180	
181	    // REWORK (round 1) — reproduces the Tester's confirmed defect directly. `capBasketQuantities`
182	    // is captured once at render time (exactly like `useWishlistAuthDrawer.ts`'s own top-level
183	    // `const {capBasketQuantities} = useCartMergeAndCap();`) while nothing is mutating, then a
184	    // real mutation starts — built directly on the cache, not through a React hook, so nothing
185	    // causes this hook instance to re-render — before the captured function is actually invoked.
186	    // This is exactly the async-gap shape `useWishlistAuthDrawer.ts` has between its own render
187	    // and its later, async `mergeBasket.mutate(...).onSuccess` invocation: nothing guarantees
188	    // that hook re-renders between capturing `capBasketQuantities` and invoking it. Before the
189	    // fix (a React-render-time `useIsMutating()` snapshot closed over by `capBasketQuantities`)
190	    // this returned `{status: 'corrected'}`, because the closure held a value frozen at the
191	    // render that produced it. Reading `queryClient.isMutating()` live, inside the function
192	    // body, at the moment it actually runs, is what makes this pass.
193	    test('a mutation that starts AFTER capBasketQuantities was captured, with no re-render in between, is still caught', async () => {
194	      const { result } = renderHookWithQueryClient(() => ({
195	        cap: useCartMergeAndCap(),
196	        queryClient: useQueryClient(),
197	      }));
198	
199	      // Captured while nothing is mutating — deliberately held in plain locals, never re-read
200	      // from `result.current` again below, so this reproduces the real bug shape regardless of
201	      // whatever React itself does or doesn't re-render internally in response to the mutation
202	      // seeded next.
203	      const { capBasketQuantities } = result.current.cap;
204	      const { queryClient } = result.current;
205	      expect(queryClient.isMutating()).toBe(0);
206	
207	      const inFlight = seedInFlightMutation(queryClient);
208	      expect(queryClient.isMutating()).toBe(1);
209	
210	      const basket = makeBasket([makeLineItem({ quantity: 5 })]);
211	      const outcome = await act(async () => capBasketQuantities(basket));
212	
213	      expect(outcome).toEqual({ status: 'skipped', reason: 'mutation-in-flight' });
214	      expect(mockMutateAsync).not.toHaveBeenCalled();
215	      inFlight.destroy();
216	    });
217	  });
218	
219	  describe('loop guard — one attempt per basket version, no retry storm', () => {
220	    test('two consecutive invocations against the same basket version issue exactly one write', async () => {
221	      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
222	      const basket = makeBasket([makeLineItem({ quantity: 5 })]);
223	
224	      const first = await act(async () => result.current.capBasketQuantities(basket));
225	      const second = await act(async () => result.current.capBasketQuantities(basket));
226	
227	      expect(first).toEqual({ status: 'corrected' });
228	      expect(second).toEqual({ status: 'skipped', reason: 'already-attempted-this-version' });
229	      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
230	    });
231	
232	    test('a server rejection surfaces an error and a later call against the same unchanged basket does not retry', async () => {
233	      mockMutateAsync.mockRejectedValueOnce(new Error('server rejected the quantity update'));
234	      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
235	      const basket = makeBasket([makeLineItem({ quantity: 5 })]);
236	
237	      const first = await act(async () => result.current.capBasketQuantities(basket));
238	      expect(first.status).toBe('error');
239	      if (first.status === 'error') {
240	        expect(first.error).toBeInstanceOf(Error);
241	      }
242	      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
243	
244	      const second = await act(async () => result.current.capBasketQuantities(basket));
245	      expect(second).toEqual({ status: 'skipped', reason: 'already-attempted-this-version' });
246	      // Still one — the rejection above did not trigger a retry, and the second call did not
247	      // either.
248	      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
249	    });
250	
251	    test('a genuinely new basket version (e.g. after a real correction changes lastModified) is free to attempt again', async () => {
252	      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
253	      const staleBasket = makeBasket([makeLineItem({ quantity: 5 })], { lastModified: 'v1' });
254	      const newerBasket = makeBasket([makeLineItem({ quantity: 5 })], { lastModified: 'v2' });
255	
256	      await act(async () => result.current.capBasketQuantities(staleBasket));
257	      const second = await act(async () => result.current.capBasketQuantities(newerBasket));
258	
259	      expect(second).toEqual({ status: 'corrected' });
260	      expect(mockMutateAsync).toHaveBeenCalledTimes(2);
261	    });
262	  });
263	
264	  describe('sequencing — resolves only once its own write settles', () => {
265	    test('a caller sequencing merge -> cap -> a resume stand-in observes merge, then cap, then resume, in that order', async () => {
266	      let resolveWrite: (value: unknown) => void = () => {};
267	      mockMutateAsync.mockImplementation(() => new Promise((resolve) => (resolveWrite = resolve)));
268	
269	      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
270	      const basket = makeBasket([makeLineItem({ quantity: 5 })]);
271	
272	      const order: string[] = [];
273	      // Neither of these represents production code from another step — both are local test
